    # Estimate future item distribution from recent history
    if recent_items:
        avg = sum(recent_items) / len(recent_items)
        sorted_r = sorted(recent_items)
        median = sorted_r[len(sorted_r) // 2]
    else:
        avg = item
        median = item

    # Classify bins into tiers based on remaining capacity
    # Tier 0: nearly full (< 15% capacity) - prefer these to close them out
    # Tier 1: medium (15-60% capacity) - use for medium items
    # Tier 2: large remaining (> 60%) - reserve for large items
    t0, t1, t2 = [], [], []
    for i, r in feasible:
        frac = r / bin_capacity
        if frac < 0.15:
            t0.append((i, r))
        elif frac < 0.60:
            t1.append((i, r))
        else:
            t2.append((i, r))

    item_frac = item / bin_capacity

    # Perfect fit always wins
    for i, r in feasible:
        if r - item < 1e-6:
            return i

    # Large items (>40% capacity): use bins with most remaining to avoid waste
    if item_frac > 0.40:
        candidates = t2 if t2 else (t1 if t1 else t0)
        return min(candidates, key=lambda x: x[1] - item)[0]

    # Small items (<12% capacity): pack into nearly-full bins first (close them)
    if item_frac < 0.12:
        if t0:
            return min(t0, key=lambda x: x[1] - item)[0]
        if t1:
            return min(t1, key=lambda x: x[1] - item)[0]
        return -1  # open new bin to preserve large bins for large items

    # Medium items: best-fit within tier1, then tier0, avoid wasting tier2
    def score_bin(r):
        leftover = r - item
        # Penalize leftovers that are awkward (too small for avg future item)
        if leftover < avg * 0.5:
            return leftover  # tight fit is good
        # Prefer leftover that's a good multiple of median future item
        n = leftover / median if median > 1e-9 else 0
        waste = (n - math.floor(n)) * median
        return leftover + waste * 2.0

    candidates = t1 if t1 else (t0 if t0 else t2)
    return min(candidates, key=lambda x: score_bin(x[1]))[0]

