        avg = sum(recent_items) / len(recent_items)
        sorted_recent = sorted(recent_items)
        median = sorted_recent[len(sorted_recent) // 2]
    else:
        avg = item
        median = item

    # Classify bins into tiers based on remaining capacity
    # Tier 0: nearly full (< 15% capacity) - perfect fit targets
    # Tier 1: medium (15-55% capacity) - usable
    # Tier 2: large (>55% capacity) - preserve for large items

    t0, t1, t2 = [], [], []
    for i, r in feasible:
        frac = r / bin_capacity
        if frac < 0.15:
            t0.append((i, r))
        elif frac < 0.55:
            t1.append((i, r))
        else:
            t2.append((i, r))

    item_frac = item / bin_capacity

    # For large items (>45% capacity), use best fit among large bins first, then all
    if item_frac > 0.45:
        pool = t2 + t1 if (t2 or t1) else feasible
    # For small items (<20% capacity), prefer nearly-full bins to close them out
    elif item_frac < 0.20:
        pool = t0 if t0 else (t1 if t1 else t2)
    # Medium items: prefer medium bins, scoring by how well leftover aligns with avg future item
    else:
        pool = t1 if t1 else (t0 if t0 else t2)

    best_idx = -1
    best_score = float('inf')

    for i, r in pool:
