            # Penalize leaving large unusable gaps relative to median item
            gap_penalty = 0.0 if leftover >= median * 0.8 else (median - leftover) / bin_capacity
            score = waste_penalty + gap_penalty * 0.5 + (leftover / bin_capacity) * 0.05

        if score < best_score:
            best_score = score
            best_idx = i

    return best_idx if best_idx >= 0 else -1

